output_text:
[
  {
    "id": "take_cart_before_shopping",
    "text": "The shopper is obliged to collect the store cart from the cart station before doing the shopping.",
    "abstraction": {
      "state_properties": {
        "at_initial_cart_station": "at(1,5)"
      },
      "events": {
        "pickup_initial_cart": {
          "pre": {
            "and": [
              "at_initial_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_initial_cart"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Before leaving the supermarket, the shopper is obliged to return the cart to the designated cart-return bay at the northwest side of the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "The shopper is prohibited from leaving the cart anywhere other than the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_bay"
    }
  },
  {
    "id": "do_not_exit_with_cart",
    "text": "The shopper is prohibited from exiting the store while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "The shopper should only exit after the cart has been parked at the return bay, so the final exit occurs while the cart remains stationed there.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_after_cart_return": {
          "pre": {
            "and": [
              "EXIT",
              "cart_parked_at_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "exit_after_cart_return"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "The shopper is prohibited from carrying groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "The shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once the cart is parked at the return bay, the shopper is prohibited from picking it up again.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "cart_parked_at_return_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
